import { useEffect, useMemo, useState } from "react";
import { ArrowRight, BarChart3, Building2, CalendarClock, CheckCircle2, ClipboardPlus, Copy, DatabaseZap, Download, ExternalLink, Filter, IdCard, MessageCircle, PackageCheck, Pencil, Phone, RefreshCw, Search, Settings2, ShieldCheck, UserPlus, UsersRound, XCircle } from "lucide-react";
import { trpc } from "@/lib/trpc";
import { customerMessageTemplateVariables, defaultCustomerAvailabilityTemplate, defaultCustomerOrderInProgressTemplate, defaultCustomerUnavailableTemplate, renderCustomerMessageTemplate } from "@/lib/customerMessageTemplates";
import { startLogin } from "@/const";

type RequestStatus = "requested" | "awaiting_supply" | "ready_to_contact" | "contacted" | "fulfilled" | "unavailable" | "cancelled";
type SupplierArrivalStatus = "scheduled" | "arrived" | "late" | "cancelled";
type RequestEditor = { id: number; customerName: string; customerPhone: string; productName: string; productCode: string; requestedQuantity: string; note: string };
type SupplierContactEditor = { supplierId?: number; name: string; contactLabel: string; contactPhone: string; isActive: boolean };

const statusMeta: Record<RequestStatus, { label: string; className: string }> = {
  requested: { label: "مطلوب", className: "border-[#e7d7a0] bg-[#fff8de] text-[#7a5a14]" },
  awaiting_supply: { label: "جاري الطلب / توريد جزئي", className: "border-[#ead3a4] bg-[#fff8e8] text-[#816125]" },
  ready_to_contact: { label: "تم التوفير · جاهز للتواصل", className: "border-[#b8dfca] bg-[#eaf8ef] text-[#176b52]" },
  contacted: { label: "تم التواصل", className: "border-[#b8d9e6] bg-[#edf8fc] text-[#26657a]" },
  fulfilled: { label: "تم التسليم", className: "border-[#b9dfca] bg-[#e8f6ed] text-[#1f704f]" },
  unavailable: { label: "غير متوفر", className: "border-[#ead0ca] bg-[#fff1ef] text-[#9b4b40]" },
  cancelled: { label: "ملغي", className: "border-[#e7dbd8] bg-[#fbf6f5] text-[#84615c]" },
};

const arrivalMeta: Record<SupplierArrivalStatus, { label: string; className: string }> = {
  scheduled: { label: "مجدول", className: "border-[#bfd9e7] bg-[#eff8fc] text-[#26677d]" },
  arrived: { label: "وصل", className: "border-[#b8dfca] bg-[#eaf8ef] text-[#176b52]" },
  late: { label: "متأخر", className: "border-[#ead3a4] bg-[#fff8e8] text-[#816125]" },
  cancelled: { label: "ملغي", className: "border-[#ead0ca] bg-[#fff1ef] text-[#9b4b40]" },
};

function formatQuantity(value: string | number) {
  return Number(value).toLocaleString("ar-EG", { maximumFractionDigits: 3 });
}

function whatsappLink(phone: string, text: string) {
  const normalizedPhone = phone.replace(/\D/g, "");
  return `https://wa.me/${normalizedPhone}?text=${encodeURIComponent(text)}`;
}

export function CustomerRequestsCenter({ onClose }: { onClose?: () => void }) {
  const utils = trpc.useUtils();
  const auth = trpc.auth.me.useQuery(undefined, { retry: false });
  const workspaces = trpc.workspace.list.useQuery(undefined, { enabled: Boolean(auth.data), retry: false });
  const [workspaceId, setWorkspaceId] = useState<number | undefined>();
  const [joinCode, setJoinCode] = useState("");
  const [notice, setNotice] = useState("");
  const [newInviteCode, setNewInviteCode] = useState("");
  const [allocationInputs, setAllocationInputs] = useState<Record<string, string>>({});
  const [searchTerm, setSearchTerm] = useState("");
  const [statusFilter, setStatusFilter] = useState<"all" | RequestStatus>("all");
  const [selectedTemplateId, setSelectedTemplateId] = useState<number | undefined>();
  const [templateEditingId, setTemplateEditingId] = useState<number | undefined>();
  const [templateEditor, setTemplateEditor] = useState({ name: "رسالة توافر الصنف", body: defaultCustomerAvailabilityTemplate, isDefault: true, isActive: true });
  const [employeeCodes, setEmployeeCodes] = useState<Record<number, string>>({});
  const [performanceDays, setPerformanceDays] = useState(30);
  const [arrivalForm, setArrivalForm] = useState({ supplierName: "", expectedAt: new Date().toISOString().slice(0, 16), note: "" });
  const [form, setForm] = useState({ customerName: "", customerPhone: "", productName: "", productCode: "", requestedQuantity: "1", note: "" });
  const [requestEditor, setRequestEditor] = useState<RequestEditor | undefined>();
  const [supplierContactEditor, setSupplierContactEditor] = useState<SupplierContactEditor>({ name: "", contactLabel: "", contactPhone: "", isActive: true });

  const selectedWorkspace = useMemo(() => workspaces.data?.find((workspace) => workspace.workspaceId === workspaceId), [workspaces.data, workspaceId]);
  const canUseRequests = selectedWorkspace && ["owner", "manager", "customer_requests"].includes(selectedWorkspace.accessRole);
  const canApproveSupply = selectedWorkspace && ["owner", "manager"].includes(selectedWorkspace.accessRole);
  const requests = trpc.customerRequests.list.useQuery({ workspaceId: workspaceId ?? 0 }, { enabled: Boolean(workspaceId && canUseRequests), retry: false });
  const dailyWorkQueue = trpc.customerRequests.dailyWorkQueue.useQuery({ workspaceId: workspaceId ?? 0 }, { enabled: Boolean(workspaceId && canUseRequests), retry: false });
  const supplyCandidates = trpc.customerRequests.supplyCandidates.useQuery({ workspaceId: workspaceId ?? 0 }, { enabled: Boolean(workspaceId && canApproveSupply), retry: false });
  const messageTemplates = trpc.customerRequests.messageTemplates.useQuery({ workspaceId: workspaceId ?? 0 }, { enabled: Boolean(workspaceId && canUseRequests), retry: false });
  const responseMetrics = trpc.customerRequests.responseMetrics.useQuery({ workspaceId: workspaceId ?? 0 }, { enabled: Boolean(workspaceId && canApproveSupply), retry: false });
  const teamMembers = trpc.customerRequests.teamMembers.useQuery({ workspaceId: workspaceId ?? 0 }, { enabled: Boolean(workspaceId && canApproveSupply), retry: false });
  const teamPerformance = trpc.customerRequests.teamPerformance.useQuery({ workspaceId: workspaceId ?? 0, sinceDays: performanceDays }, { enabled: Boolean(workspaceId && canApproveSupply), retry: false });
  const supplierArrivals = trpc.supplierArrivals.list.useQuery({ workspaceId: workspaceId ?? 0 }, { enabled: Boolean(workspaceId && canApproveSupply), retry: false });
  const supplierContacts = trpc.supplierContacts.list.useQuery({ workspaceId: workspaceId ?? 0 }, { enabled: Boolean(workspaceId && canApproveSupply), retry: false });
  const reliabilitySnapshot = trpc.governance.reliabilitySnapshot.useQuery({ workspaceId: workspaceId ?? 0 }, { enabled: Boolean(workspaceId && canApproveSupply), retry: false });

  useEffect(() => {
    if (workspaceId || !workspaces.data?.length) return;
    const suitable = workspaces.data.find((workspace) => workspace.accessRole === "customer_requests") ?? workspaces.data.find((workspace) => ["owner", "manager"].includes(workspace.accessRole));
    setWorkspaceId(suitable?.workspaceId);
  }, [workspaceId, workspaces.data]);

  useEffect(() => {
    if (selectedTemplateId || !messageTemplates.data?.length) return;
    setSelectedTemplateId(messageTemplates.data.find((template) => template.isDefault)?.id ?? messageTemplates.data[0]?.id);
  }, [selectedTemplateId, messageTemplates.data]);

  const createRequest = trpc.customerRequests.create.useMutation({
    onSuccess: async (result) => {
      if (result.duplicate) setNotice("يوجد طلب مفتوح سابق لنفس العميل والصنف؛ لم ننشئ سجلًا مكررًا.");
      else { setNotice("تم تسجيل طلب العميل في قائمة المتابعة."); setForm({ customerName: "", customerPhone: "", productName: "", productCode: "", requestedQuantity: "1", note: "" }); }
      await utils.customerRequests.list.invalidate();
    },
    onError: (error) => setNotice(error.message),
  });
  const setStatus = trpc.customerRequests.setStatus.useMutation({
    onSuccess: async () => { await utils.customerRequests.list.invalidate(); },
    onError: (error) => setNotice(error.message),
  });
  const approveSupply = trpc.customerRequests.approveSupply.useMutation({
    onSuccess: async (updated) => { setNotice(`تم اعتماد تخصيص التوريد لـ ${updated.length.toLocaleString("ar-EG")} طلب/طلبات. راجع قائمة «جاهز للتواصل».`); await Promise.all([utils.customerRequests.list.invalidate(), utils.customerRequests.supplyCandidates.invalidate()]); },
    onError: (error) => setNotice(error.message),
  });
  const createInvite = trpc.customerRequests.createTeamInvite.useMutation({
    onSuccess: (result) => { setNewInviteCode(result.code); setNotice("ظهر رمز أحادي الاستخدام؛ شاركه مع الزميل عبر قناة آمنة قبل انتهاء صلاحيته."); },
    onError: (error) => setNotice(error.message),
  });
  const redeemInvite = trpc.customerRequests.redeemTeamInvite.useMutation({
    onSuccess: async () => { setNotice("تم انضمامك إلى فريق طلبات العملاء. اختر مساحة الصيدلية من القائمة."); setJoinCode(""); await workspaces.refetch(); },
    onError: (error) => setNotice(error.message),
  });
  const saveMessageTemplate = trpc.customerRequests.saveMessageTemplate.useMutation({
    onSuccess: async () => { setNotice("حُفظ قالب WhatsApp المعتمد. يظل فتح الرسالة وإرسالها بقرار الموظف."); await utils.customerRequests.messageTemplates.invalidate(); },
    onError: (error) => setNotice(error.message),
  });
  const ensureWorkspace = trpc.workspace.ensure.useMutation({
    onSuccess: async (workspace) => { setWorkspaceId(workspace.workspaceId); setNotice("تم تجهيز مساحة العمل. يمكنك الآن تسجيل طلب العميل بأمان."); await workspaces.refetch(); },
    onError: (error) => setNotice(error.message),
  });
  const setEmployeeCode = trpc.customerRequests.setEmployeeCode.useMutation({
    onSuccess: async () => { setNotice("تم حفظ كود الموظف داخل مساحة العمل."); await Promise.all([utils.customerRequests.teamMembers.invalidate(), utils.customerRequests.teamPerformance.invalidate()]); },
    onError: (error) => setNotice(error.message),
  });
  const createSupplierArrival = trpc.supplierArrivals.create.useMutation({
    onSuccess: async () => { setNotice("تمت إضافة موعد وصول المورد إلى قائمة الانتظار."); setArrivalForm({ supplierName: "", expectedAt: new Date().toISOString().slice(0, 16), note: "" }); await utils.supplierArrivals.list.invalidate(); },
    onError: (error) => setNotice(error.message),
  });
  const setSupplierArrivalStatus = trpc.supplierArrivals.setStatus.useMutation({
    onSuccess: async () => { setNotice("تم تحديث حالة موعد المورد."); await utils.supplierArrivals.list.invalidate(); },
    onError: (error) => setNotice(error.message),
  });
  const updateRequestDetails = trpc.customerRequests.updateDetails.useMutation({
    onSuccess: async () => { setNotice("تم حفظ تعديل طلب العميل وسُجّل نوع التعديل في سجل التشغيل."); setRequestEditor(undefined); await Promise.all([utils.customerRequests.list.invalidate(), utils.customerRequests.supplyCandidates.invalidate(), utils.customerRequests.responseMetrics.invalidate()]); },
    onError: (error) => setNotice(error.message),
  });
  const saveSupplierContact = trpc.supplierContacts.save.useMutation({
    onSuccess: async () => { setNotice("تم حفظ جهة المورد ورقم التواصل. فتح WhatsApp، إن استُخدم، يبقى مراجعة يدوية فقط."); setSupplierContactEditor({ name: "", contactLabel: "", contactPhone: "", isActive: true }); await utils.supplierContacts.list.invalidate(); },
    onError: (error) => setNotice(error.message),
  });
  const exportOperationalSnapshot = trpc.governance.exportOperationalSnapshot.useMutation({
    onSuccess: (snapshot) => {
      const blob = new Blob([JSON.stringify(snapshot, null, 2)], { type: "application/json;charset=utf-8" });
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = `pharmacy-operational-snapshot-${new Date().toISOString().slice(0, 10)}.json`;
      link.click();
      URL.revokeObjectURL(url);
      setNotice("تم تنزيل لقطة تشغيلية محلية. راجع نطاقها قبل حفظها؛ لا تتضمن Excel أو صور الفواتير أو OCR الخام.");
    },
    onError: (error) => setNotice(error.message),
  });

  function submitRequest(event: React.FormEvent) {
    event.preventDefault();
    if (!auth.data) { setNotice("سجّل الدخول أولًا لحفظ طلبات العملاء داخل مساحة العمل الآمنة."); startLogin(); return; }
    if (!workspaceId) return setNotice("اختر مساحة الصيدلية أولًا.");
    createRequest.mutate({ workspaceId, ...form, productCode: form.productCode.trim() || undefined, note: form.note.trim() || undefined });
  }

  function startRequestEdit(request: { id: number; customerName: string; customerPhone: string; productName: string; productCode?: string | null; requestedQuantity: string; note?: string | null }) {
    setRequestEditor({ id: request.id, customerName: request.customerName, customerPhone: request.customerPhone, productName: request.productName, productCode: request.productCode ?? "", requestedQuantity: request.requestedQuantity, note: request.note ?? "" });
  }

  function submitRequestEdit(event: React.FormEvent) {
    event.preventDefault();
    if (!workspaceId || !requestEditor) return;
    updateRequestDetails.mutate({ workspaceId, customerRequestId: requestEditor.id, customerName: requestEditor.customerName, customerPhone: requestEditor.customerPhone, productName: requestEditor.productName, productCode: requestEditor.productCode.trim() || undefined, requestedQuantity: requestEditor.requestedQuantity, note: requestEditor.note.trim() || undefined });
  }

  function openWhatsApp(request: { id: number; customerPhone: string; customerName: string; productName: string; productCode?: string | null; requestedQuantity: string }) {
    if (!workspaceId) return;
    const selectedTemplate = messageTemplates.data?.find((template) => template.id === selectedTemplateId);
    const message = renderCustomerMessageTemplate(selectedTemplate?.body ?? defaultCustomerAvailabilityTemplate, request);
    setStatus.mutate({ workspaceId, customerRequestId: request.id, status: "contacted", note: "فتح الموظف رسالة WhatsApp الجاهزة بعد مراجعة إتاحة الصنف." }, {
      onSuccess: () => {
        window.open(whatsappLink(request.customerPhone, message), "_blank", "noopener,noreferrer");
        setNotice("سُجّل فتح رسالة WhatsApp، ولم يُرسل شيء من الأداة تلقائيًا.");
      },
    });
  }

  function markOrderingAndOpenWhatsApp(request: { id: number; customerPhone: string; customerName: string; productName: string; productCode?: string | null; requestedQuantity: string }) {
    if (!workspaceId) return;
    const message = renderCustomerMessageTemplate(defaultCustomerOrderInProgressTemplate, request);
    setStatus.mutate({ workspaceId, customerRequestId: request.id, status: "awaiting_supply", note: "اعتمد المدير حالة جاري الطلب وفتح رسالة تحديث العميل للمراجعة." }, {
      onSuccess: () => {
        window.open(whatsappLink(request.customerPhone, message), "_blank", "noopener,noreferrer");
        setNotice("سُجلت حالة «جاري الطلب» وفُتحت رسالة مراجعة للعميل؛ الإرسال قرار الموظف داخل WhatsApp.");
      },
    });
  }

  function markUnavailableAndOpenWhatsApp(request: { id: number; customerPhone: string; customerName: string; productName: string; productCode?: string | null; requestedQuantity: string }) {
    if (!workspaceId) return;
    const reason = window.prompt("اكتب سبب عدم التوفر ليُحفظ في السجل:");
    if (!reason?.trim()) return;
    const message = renderCustomerMessageTemplate(defaultCustomerUnavailableTemplate, request);
    setStatus.mutate({ workspaceId, customerRequestId: request.id, status: "unavailable", closedReason: reason.trim(), note: "قرر المدير عدم التوفر وفتح رسالة اعتذار للمراجعة." }, {
      onSuccess: () => {
        window.open(whatsappLink(request.customerPhone, message), "_blank", "noopener,noreferrer");
        setNotice("سُجلت حالة «غير متوفر» وفُتحت رسالة مراجعة للعميل؛ لا ترسل الأداة الرسالة تلقائيًا.");
      },
    });
  }

  const allRequests = requests.data ?? [];
  const readyCount = allRequests.filter((request) => request.status === "ready_to_contact").length;
  const openCount = allRequests.filter((request) => ["requested", "awaiting_supply"].includes(request.status)).length;
  const orderingCount = allRequests.filter((request) => request.status === "awaiting_supply").length;
  const lateArrivalCount = (supplierArrivals.data ?? []).filter((schedule) => schedule.status === "late").length;
  const normalizedSearch = searchTerm.trim().toLocaleLowerCase("ar");
  const filteredRequests = allRequests.filter((request) => {
    const matchesStatus = statusFilter === "all" || request.status === statusFilter;
    const matchesSearch = !normalizedSearch || `${request.customerName} ${request.customerPhone} ${request.productName} ${request.productCode ?? ""}`.toLocaleLowerCase("ar").includes(normalizedSearch);
    return matchesStatus && matchesSearch;
  });
  const activeRequests = filteredRequests;

  if (!auth.isLoading && !auth.data) return <section dir="rtl" className="mx-auto max-w-2xl rounded-3xl border border-[#cbe1d5] bg-[linear-gradient(130deg,#123c37,#1e5c50)] p-6 text-center text-white shadow-[0_16px_36px_rgba(19,62,54,.16)] sm:p-8"><UsersRound className="mx-auto size-9 text-[#deb766]" /><h2 className="mt-3 display-font text-2xl font-semibold">سجّل الدخول لحفظ طلبات العملاء</h2><p className="mx-auto mt-2 max-w-lg text-xs leading-6 text-[#d5e8e0]">تظهر حماية الدخول لأن طلبات العملاء وبيانات التواصل محفوظة في مساحة عمل الصيدلية. بعد الدخول ستظهر مساحة العمل ونموذج التسجيل مباشرة.</p><button type="button" onClick={startLogin} className="mt-5 inline-flex min-h-11 items-center gap-2 rounded-xl bg-[#f0d18b] px-4 py-2.5 text-xs font-bold text-[#173f38] hover:bg-[#f7dfaa]"><ShieldCheck className="size-4" />تسجيل الدخول الآمن</button>{onClose && <button type="button" onClick={onClose} className="mr-2 mt-5 inline-flex min-h-11 items-center gap-2 rounded-xl border border-white/20 bg-white/10 px-4 py-2.5 text-xs font-bold hover:bg-white/15"><ArrowRight className="size-4" />العودة</button>}</section>;

  if (!workspaces.isLoading && !workspaces.data?.length) return <section dir="rtl" className="mx-auto max-w-2xl rounded-3xl border border-[#cbe1d5] bg-white p-6 text-center shadow-sm sm:p-8"><ShieldCheck className="mx-auto size-9 text-[#176f59]" /><h2 className="mt-3 display-font text-2xl font-semibold text-[#214b41]">جهّز مساحة عمل الصيدلية</h2><p className="mx-auto mt-2 max-w-lg text-xs leading-6 text-[#71867d]">الحساب مسجّل، لكن لا توجد مساحة عمل مرتبطة به بعد. تُنشأ مساحة خاصة بك عند التأكيد، ثم يصبح حفظ الطلبات متاحًا.</p><button type="button" onClick={() => ensureWorkspace.mutate()} disabled={ensureWorkspace.isPending} className="mt-5 inline-flex min-h-11 items-center gap-2 rounded-xl bg-[#123c37] px-4 py-2.5 text-xs font-bold text-white hover:bg-[#17574b] disabled:opacity-60"><ShieldCheck className="size-4" />{ensureWorkspace.isPending ? "جارٍ تجهيز المساحة…" : "تجهيز مساحة العمل"}</button>{onClose && <button type="button" onClick={onClose} className="mr-2 mt-5 inline-flex min-h-11 items-center gap-2 rounded-xl border border-[#cfe0d8] bg-white px-4 py-2.5 text-xs font-bold text-[#3d685d] hover:bg-[#f4faf6]"><ArrowRight className="size-4" />العودة</button>}</section>;

  return <section dir="rtl" className="mx-auto max-w-6xl space-y-5">
    <header className="rounded-3xl border border-[#cbe1d5] bg-[linear-gradient(130deg,#123c37,#1e5c50)] p-5 text-white shadow-[0_16px_36px_rgba(19,62,54,.16)] sm:p-7">
      <div className="flex flex-wrap items-start justify-between gap-4"><div><div className="flex items-center gap-2 text-[#c7e4d9]"><UsersRound className="size-5 text-[#deb766]" /><span className="text-[11px] font-bold tracking-[.1em]">{canApproveSupply ? "بوابة المدير · قيادة الطلبات" : "بوابة الموظف · طلبات العملاء"}</span></div><h2 className="mt-2 display-font text-2xl font-semibold">{canApproveSupply ? "لوحة قيادة التوريد والتواصل" : "مساحة عمل طلبات العملاء"}</h2><p className="mt-2 max-w-2xl text-xs leading-6 text-[#d5e8e0]">{canApproveSupply ? "تراجع ما يحتاج طلبًا، تعتمد التوريد من فاتورة موثقة، ثم تتابع الإتاحة والتواصل. لا تُرسل أي رسالة تلقائيًا." : "تسجل طلبات العملاء وتتابع التواصل والتسليم فقط. لا ترى ملفات Excel أو الفواتير أو اعتمادات المدير."}</p></div>{onClose && <button type="button" onClick={onClose} className="inline-flex items-center gap-2 rounded-xl border border-white/20 bg-white/10 px-3 py-2 text-xs font-bold hover:bg-white/15"><ArrowRight className="size-4" />العودة</button>}</div>
      <div className="mt-5 grid gap-2 sm:grid-cols-3"><Metric label={canApproveSupply ? "طلبات تحتاج قرارًا" : "طلباتي المفتوحة"} value={openCount} tone="amber" /><Metric label="تم التوفير" value={readyCount} tone="green" /><Metric label="صلاحية الجلسة" value={selectedWorkspace ? (selectedWorkspace.accessRole === "customer_requests" ? "موظف طلبات" : "مدير") : "—"} tone="plain" /></div>
    </header>

    {canApproveSupply ? <section className="grid gap-3 sm:grid-cols-3"><DecisionCard icon={PackageCheck} title="جاري الطلب" value={orderingCount} note="طلبات بدأ توفيرها وتحتاج متابعة العميل." tone="amber" /><DecisionCard icon={MessageCircle} title="تم التوفير" value={readyCount} note="طلبات تحتاج رسالة توافر أو متابعة تسليم." tone="green" /><DecisionCard icon={CalendarClock} title="وصول مورد متأخر" value={lateArrivalCount} note="راجع الموعد قبل أن تتأخر طلبات العملاء." tone="rose" /></section> : <section className="rounded-2xl border border-[#c9e4d7] bg-[#f0faf4] p-4"><div className="flex items-start gap-3"><ClipboardPlus className="mt-0.5 size-5 text-[#1b725b]" /><div><h3 className="text-sm font-bold text-[#214b41]">مهمتك الآن</h3><p className="mt-1 text-[11px] leading-5 text-[#638078]">سجل طلب العميل بدقة. عندما يعتمد المدير التوريد ستظهر لك حالة «تم التوفير» وزر رسالة WhatsApp للمراجعة. لا تحتاج إلى فتح أي شاشة إدارية أخرى.</p></div></div></section>}

    {canApproveSupply && <section className="rounded-2xl border border-[#e3d5ad] bg-[#fffdf6] p-4 sm:p-5"><div className="flex items-start gap-3"><PackageCheck className="mt-0.5 size-5 text-[#8f6a1d]" /><div><h3 className="text-sm font-bold text-[#634f18]">قرارات المدير السريعة</h3><p className="mt-1 text-[10px] leading-5 text-[#806d38]">اختر «جاري الطلب» لإبلاغ العميل بأن التوفير بدأ، أو «غير متوفر» مع سبب. الرسالتان تفتحان للمراجعة ولا ترسلان تلقائيًا.</p></div></div><div className="mt-4 grid gap-2 lg:grid-cols-2">{allRequests.filter((request) => ["requested", "awaiting_supply"].includes(request.status)).slice(0, 8).map((request) => <div key={`manager-action-${request.id}`} className="rounded-xl border border-[#eadfbd] bg-white p-3"><div className="flex items-start justify-between gap-2"><div><p className="text-xs font-bold text-[#5b4e25]">{request.productName}</p><p className="mt-1 text-[10px] text-[#806f43]">{request.customerName} · {formatQuantity(request.requestedQuantity)}</p></div><span className={`rounded-md border px-2 py-1 text-[9px] font-bold ${statusMeta[request.status as RequestStatus].className}`}>{statusMeta[request.status as RequestStatus].label}</span></div><div className="mt-3 flex flex-wrap gap-2">{request.status === "requested" && <button type="button" onClick={() => markOrderingAndOpenWhatsApp(request)} disabled={setStatus.isPending} className="rounded-lg bg-[#80662a] px-2.5 py-2 text-[10px] font-bold text-white hover:bg-[#977a31] disabled:opacity-50">جاري الطلب + رسالة</button>}<button type="button" onClick={() => markUnavailableAndOpenWhatsApp(request)} disabled={setStatus.isPending} className="rounded-lg border border-[#ead1cb] bg-white px-2.5 py-2 text-[10px] font-bold text-[#a24b40] hover:bg-[#fff4f2] disabled:opacity-50">غير متوفر + رسالة</button></div></div>)}{!allRequests.some((request) => ["requested", "awaiting_supply"].includes(request.status)) && <p className="rounded-xl border border-dashed border-[#e5d9b3] px-3 py-5 text-center text-[10px] text-[#786c49] lg:col-span-2">لا توجد طلبات تحتاج قرار توريد أو عدم توفر الآن.</p>}</div></section>}

    <section className="rounded-2xl border border-[#dce9e2] bg-white p-4 sm:p-5"><div className="flex flex-wrap items-end justify-between gap-3"><div><p className="text-sm font-bold text-[#204940]">مساحة العمل والصلاحية</p><p className="mt-1 text-[11px] text-[#71877d]">فريق طلبات العملاء لا يرى Excel أو صور الفواتير أو قرارات اعتماد الموردين.</p></div><select value={workspaceId ?? ""} onChange={(event) => { setWorkspaceId(Number(event.target.value) || undefined); setSelectedTemplateId(undefined); }} className="min-w-56 rounded-xl border border-[#cbded4] bg-[#f9fcf9] px-3 py-2.5 text-xs font-bold text-[#284f45] outline-none focus:border-[#159174]"><option value="">اختر مساحة الصيدلية</option>{workspaces.data?.map((workspace) => <option key={workspace.workspaceId} value={workspace.workspaceId}>{workspace.workspaceName} — {workspace.accessRole === "customer_requests" ? "فريق الطلبات" : workspace.accessRole}</option>)}</select></div></section>

    {canApproveSupply && <section className="rounded-2xl border border-[#c9e3d5] bg-[#f8fcf9] p-4 sm:p-5"><div className="flex items-start gap-3"><BarChart3 className="mt-0.5 size-5 text-[#176f59]" /><div><h3 className="text-sm font-bold text-[#214b41]">لوحة زمن الاستجابة</h3><p className="mt-1 text-[10px] leading-5 text-[#71867d]">تحسب من تواريخ طلب العميل والإتاحة والتواصل والتسليم المسجلة فعليًا؛ لا تعتمد على توقعات أو بيانات تجريبية.</p></div></div><div className="mt-4 grid gap-2 sm:grid-cols-2 lg:grid-cols-4"><InsightMetric label="طلبات مفتوحة" value={responseMetrics.data?.openCount} suffix="طلب" tone="slate" /><InsightMetric label="متأخر أكثر من 24 ساعة" value={responseMetrics.data?.overdueCount} suffix="طلب" tone="amber" /><InsightMetric label="متوسط حتى الإتاحة" value={responseMetrics.data?.averageHoursToReady} suffix="ساعة" tone="green" /><InsightMetric label="متوسط من الإتاحة للتواصل" value={responseMetrics.data?.averageMinutesToContact} suffix="دقيقة" tone="blue" /></div></section>}

    {canApproveSupply && <section className="grid gap-5 xl:grid-cols-2"><section className="rounded-2xl border border-[#d5e5de] bg-white p-4 sm:p-5"><div className="flex items-start justify-between gap-3"><div className="flex items-start gap-3"><IdCard className="mt-0.5 size-5 text-[#1e745d]" /><div><h3 className="text-sm font-bold text-[#244d44]">أكواد الموظفين وأداء فريق الطلبات</h3><p className="mt-1 text-[10px] leading-5 text-[#71867d]">الكود فريد داخل الصيدلية. التقرير يستند إلى أحداث إنشاء الطلب والتواصل والتسليم والإلغاء المسجلة فعليًا.</p></div></div><select value={performanceDays} onChange={(event) => setPerformanceDays(Number(event.target.value))} className="rounded-lg border border-[#d4e2db] bg-[#fbfdfb] px-2 py-1.5 text-[10px] font-bold text-[#345e53]"><option value={7}>7 أيام</option><option value={30}>30 يومًا</option><option value={90}>90 يومًا</option></select></div><div className="mt-4 space-y-2">{teamPerformance.data?.length ? teamPerformance.data.map((employee) => <div key={employee.userId} className="rounded-xl border border-[#e0ebe5] bg-[#fbfdfb] p-3"><div className="flex items-center justify-between gap-2"><p className="text-xs font-bold text-[#234c42]">{employee.name}</p><code className="rounded-md bg-[#edf7f1] px-2 py-1 text-[9px] font-bold text-[#227154]">{employee.employeeCode ?? "بلا كود"}</code></div><div className="mt-2 grid grid-cols-4 gap-1.5 text-center text-[9px]"><MiniMetric label="سجّل" value={employee.createdCount} /><MiniMetric label="تواصل" value={employee.contactedCount} /><MiniMetric label="سلّم" value={employee.fulfilledCount} /><MiniMetric label="دقائق الرد" value={employee.averageMinutesToContact === null ? "—" : Math.round(employee.averageMinutesToContact)} /></div></div>) : <p className="rounded-xl border border-dashed border-[#d8e7df] px-3 py-4 text-center text-[10px] text-[#72877f]">لا توجد أحداث فريق ضمن الفترة المختارة بعد.</p>}</div><div className="mt-4 border-t border-[#e1ebe5] pt-3"><p className="text-[10px] font-bold text-[#587168]">تعيين كود لكل موظف</p><div className="mt-2 space-y-2">{teamMembers.data?.map((member) => <div key={member.userId} className="flex flex-wrap items-center gap-2 rounded-xl border border-[#e0ebe5] bg-white p-2.5"><span className="min-w-28 flex-1 text-[10px] font-bold text-[#284f45]">{member.name?.trim() || "موظف غير مسمى"}</span><input aria-label={`كود الموظف ${member.name ?? member.userId}`} value={employeeCodes[member.userId] ?? member.employeeCode ?? ""} onChange={(event) => setEmployeeCodes({ ...employeeCodes, [member.userId]: event.target.value.toUpperCase() })} placeholder="مثل EMP-01" className="w-28 rounded-lg border border-[#d2e1d9] bg-[#fbfdfb] px-2 py-2 text-center text-[10px] font-bold text-[#244d44] outline-none focus:border-[#159174]" /><button type="button" onClick={() => workspaceId && setEmployeeCode.mutate({ workspaceId, userId: member.userId, employeeCode: employeeCodes[member.userId] ?? member.employeeCode ?? "" })} disabled={setEmployeeCode.isPending || !(employeeCodes[member.userId] ?? member.employeeCode)?.trim()} className="rounded-lg bg-[#174d42] px-2.5 py-2 text-[10px] font-bold text-white hover:bg-[#226552] disabled:opacity-50">حفظ الكود</button></div>)}</div></div></section><section className="rounded-2xl border border-[#d5e5de] bg-white p-4 sm:p-5"><div className="flex items-start gap-3"><CalendarClock className="mt-0.5 size-5 text-[#1e745d]" /><div><h3 className="text-sm font-bold text-[#244d44]">قائمة انتظار وصول الموردين</h3><p className="mt-1 text-[10px] leading-5 text-[#71867d]">تتبع موعد الاستلام فقط. لا تغيّر الجدولة مخزونًا أو فاتورة أو طلبًا إلا عندما يراجع المدير التوريد ويعتمده.</p></div></div><form onSubmit={(event) => { event.preventDefault(); if (!workspaceId) return; const expectedAt = new Date(arrivalForm.expectedAt); if (Number.isNaN(expectedAt.getTime())) return setNotice("أدخل موعد وصول صحيحًا."); createSupplierArrival.mutate({ workspaceId, supplierName: arrivalForm.supplierName, expectedAt, note: arrivalForm.note.trim() || undefined }); }} className="mt-4 grid gap-2 sm:grid-cols-2"><input value={arrivalForm.supplierName} onChange={(event) => setArrivalForm({ ...arrivalForm, supplierName: event.target.value })} placeholder="اسم المورد" required className="min-h-10 rounded-xl border border-[#d2e1d9] bg-[#fbfdfb] px-3 text-xs font-bold text-[#244d44] outline-none focus:border-[#159174]" /><input value={arrivalForm.expectedAt} onChange={(event) => setArrivalForm({ ...arrivalForm, expectedAt: event.target.value })} type="datetime-local" required className="min-h-10 rounded-xl border border-[#d2e1d9] bg-[#fbfdfb] px-3 text-xs font-bold text-[#244d44] outline-none focus:border-[#159174]" /><input value={arrivalForm.note} onChange={(event) => setArrivalForm({ ...arrivalForm, note: event.target.value })} placeholder="ملاحظة اختيارية: رقم الطلب أو ما يلزم" className="min-h-10 rounded-xl border border-[#d2e1d9] bg-[#fbfdfb] px-3 text-xs font-bold text-[#244d44] outline-none focus:border-[#159174] sm:col-span-2" /><button disabled={createSupplierArrival.isPending || !arrivalForm.supplierName.trim()} className="inline-flex min-h-10 items-center justify-center gap-2 rounded-xl bg-[#123c37] px-3 py-2 text-xs font-bold text-white hover:bg-[#17574b] disabled:opacity-50 sm:col-span-2"><CalendarClock className="size-4" />{createSupplierArrival.isPending ? "جارٍ إضافة الموعد…" : "إضافة موعد وصول"}</button></form><div className="mt-4 space-y-2">{supplierArrivals.data?.length ? supplierArrivals.data.map((schedule) => { const meta = arrivalMeta[schedule.status as SupplierArrivalStatus]; return <div key={schedule.id} className="rounded-xl border border-[#e0ebe5] bg-[#fbfdfb] p-3"><div className="flex items-start justify-between gap-2"><div><p className="text-xs font-bold text-[#254c42]">{schedule.supplierName}</p><p className="mt-1 text-[9px] text-[#71867d]">{new Date(schedule.expectedAt).toLocaleString("ar-EG", { dateStyle: "medium", timeStyle: "short" })}</p></div><span className={`rounded-md border px-2 py-1 text-[9px] font-bold ${meta.className}`}>{meta.label}</span></div>{schedule.note && <p className="mt-2 text-[9px] leading-4 text-[#6f827a]">{schedule.note}</p>}<div className="mt-2 flex flex-wrap gap-1.5">{(["arrived", "late", "cancelled"] as SupplierArrivalStatus[]).filter((status) => status !== schedule.status).map((status) => <button key={status} type="button" onClick={() => workspaceId && setSupplierArrivalStatus.mutate({ workspaceId, scheduleId: schedule.id, status })} disabled={setSupplierArrivalStatus.isPending} className="rounded-lg border border-[#d4e2da] bg-white px-2 py-1.5 text-[9px] font-bold text-[#456c60] hover:bg-[#eef8f2]">تعيين: {arrivalMeta[status].label}</button>)}</div></div>; }) : <p className="rounded-xl border border-dashed border-[#d8e7df] px-3 py-5 text-center text-[10px] text-[#72877f]">لا توجد مواعيد موردين مجدولة بعد.</p>}</div></section></section>}

    {canApproveSupply && <section className="rounded-2xl border border-[#d5e5de] bg-white p-4 sm:p-5"><div className="flex items-start gap-3"><Building2 className="mt-0.5 size-5 text-[#1e745d]" /><div><h3 className="text-sm font-bold text-[#244d44]">دفتر جهات الموردين</h3><p className="mt-1 text-[10px] leading-5 text-[#71867d]">يمكّنك من حفظ وتعديل رقم اتصال أي مورد. لا يرسل النظام رسالة ولا يغير طلبًا أو فاتورة عند حفظ الرقم.</p></div></div><form onSubmit={(event) => { event.preventDefault(); if (!workspaceId) return; saveSupplierContact.mutate({ workspaceId, ...supplierContactEditor, supplierId: supplierContactEditor.supplierId, contactLabel: supplierContactEditor.contactLabel.trim() || undefined, contactPhone: supplierContactEditor.contactPhone.trim() || undefined }); }} className="mt-4 grid gap-2 sm:grid-cols-2 lg:grid-cols-4"><input value={supplierContactEditor.name} onChange={(event) => setSupplierContactEditor({ ...supplierContactEditor, name: event.target.value })} placeholder="اسم المورد" required className="min-h-10 rounded-xl border border-[#d2e1d9] bg-[#fbfdfb] px-3 text-xs font-bold text-[#244d44] outline-none focus:border-[#159174]" /><input value={supplierContactEditor.contactLabel} onChange={(event) => setSupplierContactEditor({ ...supplierContactEditor, contactLabel: event.target.value })} placeholder="اسم جهة الاتصال (اختياري)" className="min-h-10 rounded-xl border border-[#d2e1d9] bg-[#fbfdfb] px-3 text-xs font-bold text-[#244d44] outline-none focus:border-[#159174]" /><input value={supplierContactEditor.contactPhone} inputMode="tel" onChange={(event) => setSupplierContactEditor({ ...supplierContactEditor, contactPhone: event.target.value })} placeholder="رقم هاتف / WhatsApp" className="min-h-10 rounded-xl border border-[#d2e1d9] bg-[#fbfdfb] px-3 text-xs font-bold text-[#244d44] outline-none focus:border-[#159174]" /><button disabled={saveSupplierContact.isPending || !supplierContactEditor.name.trim()} className="inline-flex min-h-10 items-center justify-center gap-2 rounded-xl bg-[#123c37] px-3 py-2 text-xs font-bold text-white hover:bg-[#17574b] disabled:opacity-50"><Building2 className="size-4" />{saveSupplierContact.isPending ? "جارٍ الحفظ…" : supplierContactEditor.supplierId ? "حفظ تعديل المورد" : "حفظ مورد"}</button></form><div className="mt-4 grid gap-2 lg:grid-cols-2">{supplierContacts.data?.length ? supplierContacts.data.map((supplier) => <div key={supplier.id} className="rounded-xl border border-[#e0ebe5] bg-[#fbfdfb] p-3"><div className="flex items-start justify-between gap-2"><div><p className="text-xs font-bold text-[#254c42]">{supplier.name}</p><p className="mt-1 text-[10px] text-[#71867d]">{supplier.contactLabel || "لا توجد جهة اتصال مسماة"}{supplier.contactPhone ? ` · ${supplier.contactPhone}` : " · بلا رقم"}</p></div><span className={`rounded-md px-2 py-1 text-[9px] font-bold ${supplier.isActive ? "bg-[#edf8f2] text-[#247055]" : "bg-[#f3f5f4] text-[#718078]"}`}>{supplier.isActive ? "نشط" : "موقوف"}</span></div><div className="mt-3 flex flex-wrap gap-2"><button type="button" onClick={() => setSupplierContactEditor({ supplierId: supplier.id, name: supplier.name, contactLabel: supplier.contactLabel ?? "", contactPhone: supplier.contactPhone ?? "", isActive: supplier.isActive })} className="inline-flex min-h-9 items-center gap-1.5 rounded-lg border border-[#c9ddd3] bg-white px-2.5 py-1.5 text-[10px] font-bold text-[#316459] hover:bg-[#edf8f2]"><Pencil className="size-3.5" />تعديل</button>{supplier.contactPhone && <a href={whatsappLink(supplier.contactPhone, "مرحبًا، بخصوص طلب الصيدلية.")} target="_blank" rel="noreferrer" className="inline-flex min-h-9 items-center gap-1.5 rounded-lg border border-[#c9ddd3] bg-white px-2.5 py-1.5 text-[10px] font-bold text-[#316459] hover:bg-[#edf8f2]"><Phone className="size-3.5" />فتح WhatsApp للمراجعة</a>}</div></div>) : <p className="rounded-xl border border-dashed border-[#d8e7df] px-3 py-5 text-center text-[10px] text-[#72877f] lg:col-span-2">أضف أول مورد ورقم تواصله من النموذج أعلاه.</p>}</div></section>}

    <section className="grid gap-5 lg:grid-cols-[minmax(0,1.05fr)_minmax(310px,.95fr)]">
      <form onSubmit={submitRequest} className="rounded-2xl border border-[#dbe9e2] bg-white p-4 sm:p-5"><div className="flex items-center gap-2"><ClipboardPlus className="size-4 text-[#16705a]" /><h3 className="text-sm font-bold text-[#244d44]">تسجيل طلب عميل</h3></div><p className="mt-1 text-[10px] leading-5 text-[#71867d]">يمنع النظام تكرار طلب مفتوح للعميل نفسه والصنف نفسه. احفظ بيانات التواصل اللازمة فقط.</p><div className="mt-4 grid gap-3 sm:grid-cols-2"><Field label="اسم العميل" value={form.customerName} onChange={(value) => setForm({ ...form, customerName: value })} required /><Field label="رقم الهاتف / WhatsApp" value={form.customerPhone} inputMode="tel" onChange={(value) => setForm({ ...form, customerPhone: value })} required /><Field label="اسم الصنف" value={form.productName} onChange={(value) => setForm({ ...form, productName: value })} required /><Field label="كود الصنف (اختياري)" value={form.productCode} onChange={(value) => setForm({ ...form, productCode: value })} /><Field label="الكمية المطلوبة" value={form.requestedQuantity} inputMode="decimal" onChange={(value) => setForm({ ...form, requestedQuantity: value })} required /></div><label className="mt-3 block text-[10px] font-bold text-[#587168]">ملاحظة اختيارية<textarea value={form.note} onChange={(event) => setForm({ ...form, note: event.target.value })} maxLength={3000} className="mt-1.5 min-h-20 w-full rounded-xl border border-[#d2e1d9] bg-[#fbfdfb] px-3 py-2.5 text-xs text-[#244d44] outline-none focus:border-[#159174]" placeholder="مثال: بديل غير مقبول للعميل" /></label><button disabled={!canUseRequests || createRequest.isPending} className="mt-4 inline-flex min-h-11 items-center gap-2 rounded-xl bg-[#123c37] px-4 py-2.5 text-xs font-bold text-white hover:bg-[#17574b] disabled:cursor-not-allowed disabled:bg-[#8ea69d]"><ClipboardPlus className="size-4" />{createRequest.isPending ? "جارٍ الحفظ…" : "حفظ طلب العميل"}</button></form>

      <aside className="rounded-2xl border border-[#dbe9e2] bg-[#f8fbf8] p-4 sm:p-5"><div className="flex items-center gap-2"><ShieldCheck className="size-4 text-[#9c7628]" /><h3 className="text-sm font-bold text-[#274d43]">إدارة وصول الفريق</h3></div><p className="mt-1 text-[10px] leading-5 text-[#71867d]">ينشئ المدير رمزًا أحادي الاستخدام. بعد تسجيل دخول الزميل، يدخل الرمز ليحصل فقط على شاشة طلبات العملاء.</p>{canApproveSupply && <button type="button" onClick={() => workspaceId && createInvite.mutate({ workspaceId, expiresInHours: 24 })} disabled={createInvite.isPending} className="mt-4 inline-flex min-h-10 items-center gap-2 rounded-xl border border-[#b7d8c9] bg-white px-3 py-2 text-xs font-bold text-[#276655] hover:bg-[#edf8f2]"><UserPlus className="size-4" />إنشاء رمز فريق لمدة 24 ساعة</button>}{newInviteCode && <div className="mt-3 rounded-xl border border-[#d6bd78] bg-[#fff8df] p-3"><p className="text-[10px] font-bold text-[#765b18]">رمز أحادي الاستخدام — يظهر الآن فقط</p><div className="mt-2 flex items-center justify-between gap-2"><code className="select-all text-sm font-bold tracking-wider text-[#554310]">{newInviteCode}</code><button type="button" onClick={() => { void navigator.clipboard?.writeText(newInviteCode); setNotice("نُسخ رمز الانضمام. شاركه عبر قناة آمنة."); }} className="rounded-lg bg-white px-2 py-1.5 text-[#6d5313] hover:bg-[#fffdf5]" aria-label="نسخ رمز الانضمام"><Copy className="size-3.5" /></button></div></div>}<div className="mt-5 border-t border-[#dce8e1] pt-4"><label className="text-[10px] font-bold text-[#59736a]">لديك رمز انضمام<input value={joinCode} onChange={(event) => setJoinCode(event.target.value.toUpperCase())} placeholder="XXXX-XXXX-XXXX" className="mt-1.5 w-full rounded-xl border border-[#ccdcd4] bg-white px-3 py-2.5 text-xs font-bold tracking-wider text-[#284d44] outline-none focus:border-[#159174]" /></label><button type="button" onClick={() => redeemInvite.mutate({ code: joinCode })} disabled={!joinCode.trim() || redeemInvite.isPending} className="mt-2 inline-flex min-h-10 items-center gap-2 rounded-xl border border-[#b7d8c9] bg-white px-3 py-2 text-xs font-bold text-[#276655] hover:bg-[#edf8f2] disabled:opacity-50"><RefreshCw className="size-3.5" />انضمام لفريق الطلبات</button></div></aside>
    </section>

    {notice && <div role="status" className="rounded-xl border border-[#c6dfd2] bg-[#eef9f2] px-4 py-3 text-xs font-bold leading-5 text-[#236553]">{notice}</div>}

    {canApproveSupply && <section className="rounded-2xl border border-[#d9e8e1] bg-[#f8fbf8] p-4"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="text-xs font-bold text-[#244d44]">نماذج رسالة جاهزة للمدير</p><p className="mt-1 text-[10px] text-[#71867d]">اختيار النموذج لا يرسله ولا يفعّله تلقائيًا؛ راجعه ثم احفظه ضمن القوالب المعتمدة.</p></div><div className="flex flex-wrap gap-2"><button type="button" onClick={() => { setTemplateEditingId(undefined); setTemplateEditor({ name: "رسالة جاري الطلب", body: defaultCustomerOrderInProgressTemplate, isDefault: false, isActive: true }); }} className="rounded-lg border border-[#e2d1a2] bg-[#fffaf0] px-2.5 py-2 text-[10px] font-bold text-[#80651e] hover:bg-[#fff4dc]">جاري الطلب</button><button type="button" onClick={() => { setTemplateEditingId(undefined); setTemplateEditor({ name: "رسالة تم التوفير", body: defaultCustomerAvailabilityTemplate, isDefault: true, isActive: true }); }} className="rounded-lg border border-[#bdddcf] bg-[#f0faf4] px-2.5 py-2 text-[10px] font-bold text-[#23705a] hover:bg-[#e5f6ec]">تم التوفير</button><button type="button" onClick={() => { setTemplateEditingId(undefined); setTemplateEditor({ name: "رسالة عدم التوفر", body: defaultCustomerUnavailableTemplate, isDefault: false, isActive: true }); }} className="rounded-lg border border-[#ead1cb] bg-[#fff5f3] px-2.5 py-2 text-[10px] font-bold text-[#9b4b40] hover:bg-[#ffebe7]">غير متوفر</button></div></div></section>}

    {canApproveSupply && <section className="rounded-2xl border border-[#d7e6de] bg-white p-4 sm:p-5"><div className="flex items-start gap-3"><Settings2 className="mt-0.5 size-5 text-[#28755f]" /><div><h3 className="text-sm font-bold text-[#244d44]">قوالب WhatsApp المعتمدة</h3><p className="mt-1 text-[10px] leading-5 text-[#71867d]">عدّل القالب أو عيّنه افتراضيًا. لا ترسل المنصة رسالة؛ تظهر الصياغة عند فتح WhatsApp ليُراجعها الموظف أولًا.</p></div></div><div className="mt-3 flex flex-wrap gap-1.5 text-[9px] font-bold text-[#467167]"><span className="rounded-md bg-[#eff7f2] px-2 py-1">المتغيرات المتاحة:</span>{customerMessageTemplateVariables.map((variable) => <code key={variable} className="rounded-md border border-[#d6e7dd] bg-white px-2 py-1">{variable}</code>)}</div><div className="mt-4 grid gap-3 lg:grid-cols-[minmax(0,1fr)_minmax(0,1.5fr)]"><label className="text-[10px] font-bold text-[#587168]">اسم القالب<input value={templateEditor.name} onChange={(event) => setTemplateEditor({ ...templateEditor, name: event.target.value })} className="mt-1.5 w-full rounded-xl border border-[#d2e1d9] bg-[#fbfdfb] px-3 py-2.5 text-xs font-bold text-[#244d44] outline-none focus:border-[#159174]" /></label><label className="text-[10px] font-bold text-[#587168]">نص الرسالة<textarea value={templateEditor.body} onChange={(event) => setTemplateEditor({ ...templateEditor, body: event.target.value })} maxLength={2000} className="mt-1.5 min-h-24 w-full rounded-xl border border-[#d2e1d9] bg-[#fbfdfb] px-3 py-2.5 text-xs leading-5 text-[#244d44] outline-none focus:border-[#159174]" /></label></div><div className="mt-3 flex flex-wrap items-center gap-3"><label className="inline-flex items-center gap-2 text-[10px] font-bold text-[#466d62]"><input type="checkbox" checked={templateEditor.isDefault} onChange={(event) => setTemplateEditor({ ...templateEditor, isDefault: event.target.checked })} className="size-4 accent-[#19725d]" />القالب الافتراضي</label><label className="inline-flex items-center gap-2 text-[10px] font-bold text-[#466d62]"><input type="checkbox" checked={templateEditor.isActive} onChange={(event) => setTemplateEditor({ ...templateEditor, isActive: event.target.checked })} className="size-4 accent-[#19725d]" />متاح لفريق الطلبات</label><button type="button" onClick={() => workspaceId && saveMessageTemplate.mutate({ workspaceId, ...(templateEditingId ? { id: templateEditingId } : {}), ...templateEditor })} disabled={saveMessageTemplate.isPending || !templateEditor.name.trim() || !templateEditor.body.trim()} className="inline-flex min-h-10 items-center gap-2 rounded-xl bg-[#123c37] px-3 py-2 text-xs font-bold text-white hover:bg-[#17574b] disabled:opacity-50"><Settings2 className="size-3.5" />{templateEditingId ? "حفظ تعديل القالب" : "إضافة قالب"}</button><button type="button" onClick={() => { setTemplateEditingId(undefined); setTemplateEditor({ name: "رسالة توافر الصنف", body: defaultCustomerAvailabilityTemplate, isDefault: false, isActive: true }); }} className="rounded-xl border border-[#d1e0d8] bg-white px-3 py-2 text-xs font-bold text-[#527169]">قالب جديد</button></div><div className="mt-4 grid gap-2 sm:grid-cols-2 xl:grid-cols-3">{messageTemplates.data?.map((template) => <button type="button" key={template.id} onClick={() => { setTemplateEditingId(template.id); setTemplateEditor({ name: template.name, body: template.body, isDefault: template.isDefault, isActive: template.isActive }); }} className={`rounded-xl border p-3 text-right ${templateEditingId === template.id ? "border-[#7cbba5] bg-[#eff9f3]" : "border-[#dce9e2] bg-[#fbfdfb] hover:border-[#a7cfc0]"}`}><div className="flex items-center justify-between gap-2"><span className="text-[11px] font-bold text-[#264d43]">{template.name}</span>{template.isDefault && <span className="rounded-md bg-[#dcefe5] px-1.5 py-0.5 text-[8px] font-bold text-[#257157]">افتراضي</span>}</div><p className="mt-1 line-clamp-2 text-[9px] leading-4 text-[#71857d]">{template.body}</p><p className="mt-1 text-[8px] font-bold text-[#9a7650]">{template.isActive ? "متاح للفريق" : "مؤرشف"}</p></button>)}</div></section>}

    {canApproveSupply && <section className="rounded-2xl border border-[#ead8a9] bg-[#fffdf5] p-4 sm:p-5"><div className="flex items-start gap-3"><PackageCheck className="mt-0.5 size-5 text-[#9e7826]" /><div><h3 className="text-sm font-bold text-[#634f18]">اعتماد إتاحة من توريد موثق</h3><p className="mt-1 text-[10px] leading-5 text-[#806d38]">هذه قائمة مقترحات من بنود فواتير اعتمدها المدير. لا تتغير حالة العميل إلا إذا اخترت كمية ثم اعتمدت تخصيصها صراحةً.</p></div></div><div className="mt-4 space-y-2">{supplyCandidates.isLoading && <p className="text-xs text-[#76662e]">جارٍ فحص بنود التوريد المعتمدة…</p>}{!supplyCandidates.isLoading && !(supplyCandidates.data?.length) && <p className="rounded-xl border border-dashed border-[#e5d9b3] bg-white/70 px-3 py-4 text-center text-xs text-[#786c49]">لا توجد مطابقة جاهزة بين توريد فاتورة معتمد وطلبات العملاء المفتوحة.</p>}{supplyCandidates.data?.map((candidate) => { const key = `${candidate.customerRequestId}-${candidate.settlementLineId}`; const quantity = allocationInputs[key] ?? String(Math.min(candidate.requestedRemaining, candidate.availableQuantity)); return <div key={key} className="grid gap-2 rounded-xl border border-[#eadfbf] bg-white p-3 sm:grid-cols-[1fr_auto_auto]"><div><p className="text-xs font-bold text-[#5b4e25]">{candidate.customerName} · {candidate.productName}</p><p className="mt-1 text-[10px] text-[#806f43]">المتبقي للعميل: {formatQuantity(candidate.requestedRemaining)} · المتاح من فاتورة معتمدة: {formatQuantity(candidate.availableQuantity)} · مطابقة {candidate.matchMethod === "code" ? "بالكود" : "بالاسم"}</p></div><input aria-label={`كمية تخصيص ${candidate.productName}`} value={quantity} inputMode="decimal" onChange={(event) => setAllocationInputs({ ...allocationInputs, [key]: event.target.value })} className="w-24 rounded-lg border border-[#d8d0b3] bg-[#fffcf4] px-2 py-2 text-center text-xs font-bold text-[#594e2c] outline-none" /><button type="button" onClick={() => workspaceId && approveSupply.mutate({ workspaceId, allocations: [{ customerRequestId: candidate.customerRequestId, settlementLineId: candidate.settlementLineId, allocatedQuantity: quantity }] })} disabled={approveSupply.isPending} className="rounded-lg bg-[#695924] px-3 py-2 text-xs font-bold text-white hover:bg-[#806c2b] disabled:opacity-50">اعتماد الإتاحة</button></div>; })}</div></section>}

    <section className="rounded-2xl border border-[#d9e8e1] bg-[#f8fbf8] p-4"><div className="grid gap-3 lg:grid-cols-[minmax(0,1.5fr)_minmax(180px,.7fr)_minmax(220px,.8fr)]"><label className="relative block"><Search className="pointer-events-none absolute right-3 top-1/2 size-4 -translate-y-1/2 text-[#618178]" /><input value={searchTerm} onChange={(event) => setSearchTerm(event.target.value)} placeholder="ابحث بالعميل أو الهاتف أو الصنف أو الكود" className="min-h-11 w-full rounded-xl border border-[#cedfd7] bg-white py-2 pr-10 pl-3 text-xs font-bold text-[#244d44] outline-none focus:border-[#159174]" /></label><label className="relative block"><Filter className="pointer-events-none absolute right-3 top-1/2 size-4 -translate-y-1/2 text-[#618178]" /><select value={statusFilter} onChange={(event) => setStatusFilter(event.target.value as "all" | RequestStatus)} className="min-h-11 w-full appearance-none rounded-xl border border-[#cedfd7] bg-white py-2 pr-10 pl-3 text-xs font-bold text-[#244d44] outline-none focus:border-[#159174]"><option value="all">كل الحالات</option>{(Object.keys(statusMeta) as RequestStatus[]).map((status) => <option key={status} value={status}>{statusMeta[status].label}</option>)}</select></label><label className="block text-[10px] font-bold text-[#587168]">قالب WhatsApp المعتمد<select value={selectedTemplateId ?? ""} onChange={(event) => setSelectedTemplateId(Number(event.target.value) || undefined)} className="mt-1 min-h-9 w-full rounded-xl border border-[#cedfd7] bg-white px-3 py-2 text-xs font-bold text-[#244d44] outline-none focus:border-[#159174]"><option value="">الصياغة الافتراضية</option>{messageTemplates.data?.map((template) => <option key={template.id} value={template.id}>{template.name}{template.isDefault ? " · افتراضي" : ""}</option>)}</select></label></div><p className="mt-2 text-[10px] text-[#6d8279]">يظهر {activeRequests.length.toLocaleString("ar-EG")} من أصل {allRequests.length.toLocaleString("ar-EG")} طلب. القالب يفتح في WhatsApp للمراجعة، ولا يُرسل تلقائيًا.</p></section>

    <section className="rounded-2xl border border-[#dbe9e2] bg-white p-4 sm:p-5"><div className="flex flex-wrap items-center justify-between gap-3"><div><h3 className="text-sm font-bold text-[#244d44]">قائمة المتابعة</h3><p className="mt-1 text-[10px] text-[#71867d]">السجل يحفظ التغييرات التشغيلية. لم يُرسل WhatsApp من الأداة تلقائيًا.</p></div><span className="rounded-lg bg-[#eff7f1] px-2.5 py-1.5 text-[10px] font-bold text-[#2b6c58]">{activeRequests.length.toLocaleString("ar-EG")} طلب</span></div><div className="mt-4 grid gap-3 lg:grid-cols-2">{requests.isLoading && <p className="text-xs text-[#6c8178]">جارٍ تحميل طلبات العملاء…</p>}{!requests.isLoading && !activeRequests.length && <p className="rounded-xl border border-dashed border-[#d5e4dd] bg-[#fbfdfb] px-3 py-6 text-center text-xs text-[#71867d]">لا توجد طلبات عملاء في مساحة العمل المختارة بعد.</p>}{activeRequests.map((request) => { const meta = statusMeta[request.status as RequestStatus]; return <article key={request.id} className="rounded-2xl border border-[#e0ebe4] bg-[#fcfdfb] p-4"><div className="flex items-start justify-between gap-3"><div><p className="text-sm font-bold text-[#234c42]">{request.productName}</p><p className="mt-1 text-[10px] text-[#74887f]">{request.customerName} · {request.customerPhone}</p>{request.productCode && <p className="mt-1 font-mono text-[10px] text-[#6e847a]">{request.productCode}</p>}</div><span className={`rounded-lg border px-2 py-1 text-[10px] font-bold ${meta.className}`}>{meta.label}</span></div><div className="mt-3 flex items-center justify-between rounded-xl bg-[#f2f7f3] px-3 py-2 text-[10px] text-[#607970]"><span>مطلوب: <b>{formatQuantity(request.requestedQuantity)}</b></span><span>مخصّص: <b>{formatQuantity(request.allocatedQuantity)}</b></span></div>{request.note && <p className="mt-2 text-[10px] leading-5 text-[#6e8179]">{request.note}</p>}<div className="mt-3 flex flex-wrap gap-2">{request.status === "ready_to_contact" && <button type="button" onClick={() => openWhatsApp(request)} disabled={setStatus.isPending} className="inline-flex min-h-10 items-center gap-2 rounded-lg bg-[#197b5f] px-3 py-2 text-xs font-bold text-white hover:bg-[#12694f]"><MessageCircle className="size-4" />فتح WhatsApp وتسجيل التواصل<ExternalLink className="size-3" /></button>}{request.status === "contacted" && <button type="button" onClick={() => workspaceId && setStatus.mutate({ workspaceId, customerRequestId: request.id, status: "fulfilled", note: "أكد الموظف اكتمال تسليم طلب العميل." })} className="inline-flex min-h-10 items-center gap-2 rounded-lg border border-[#b6d7c8] bg-[#eef8f2] px-3 py-2 text-xs font-bold text-[#1f6b53]"><CheckCircle2 className="size-4" />تأكيد التسليم</button>}{["requested", "awaiting_supply", "ready_to_contact", "contacted"].includes(request.status) && <button type="button" onClick={() => { const reason = window.prompt("اكتب سبب الإلغاء ليُحفظ في سجل الطلب:"); if (reason && workspaceId) setStatus.mutate({ workspaceId, customerRequestId: request.id, status: "cancelled", closedReason: reason }); }} className="inline-flex min-h-10 items-center gap-2 rounded-lg border border-[#ead1cb] bg-white px-3 py-2 text-xs font-bold text-[#a24b40] hover:bg-[#fff4f2]"><XCircle className="size-4" />إلغاء بسبب</button>}</div></article>; })}</div></section>
    {canApproveSupply && <section className="rounded-2xl border border-[#c9e3d5] bg-[#f8fcf9] p-4 sm:p-5"><div className="flex items-start gap-3"><Pencil className="mt-0.5 size-5 text-[#1e745d]" /><div><h3 className="text-sm font-bold text-[#244d44]">تحرير بيانات طلب العميل</h3><p className="mt-1 text-[10px] leading-5 text-[#71867d]">اختر أي طلب لتعديل الاسم أو الرقم أو الصنف أو الكمية أو الملاحظة. لا يمكن تغيير صنف له توريد معتمد، ولا خفض الكمية عن الكمية المعتمدة؛ بذلك لا تنكسر مطابقة الفاتورة.</p></div></div><label className="mt-4 block text-[10px] font-bold text-[#587168]">اختر طلبًا للتحرير<select value={requestEditor?.id ?? ""} onChange={(event) => { const selected = allRequests.find((request) => request.id === Number(event.target.value)); if (selected) startRequestEdit(selected); else setRequestEditor(undefined); }} className="mt-1.5 min-h-10 w-full rounded-xl border border-[#d2e1d9] bg-white px-3 text-xs font-bold text-[#244d44] outline-none focus:border-[#159174]"><option value="">اختر من قائمة الطلبات</option>{allRequests.map((request) => <option key={request.id} value={request.id}>#{request.id} · {request.customerName} · {request.productName} · {statusMeta[request.status as RequestStatus].label}</option>)}</select></label>{requestEditor && <form onSubmit={submitRequestEdit} className="mt-4 rounded-xl border border-[#d8e8df] bg-white p-3"><div className="grid gap-3 sm:grid-cols-2"><Field label="اسم العميل" value={requestEditor.customerName} onChange={(value) => setRequestEditor({ ...requestEditor, customerName: value })} required /><Field label="رقم الهاتف / WhatsApp" value={requestEditor.customerPhone} inputMode="tel" onChange={(value) => setRequestEditor({ ...requestEditor, customerPhone: value })} required /><Field label="اسم الصنف" value={requestEditor.productName} onChange={(value) => setRequestEditor({ ...requestEditor, productName: value })} required /><Field label="كود الصنف (اختياري)" value={requestEditor.productCode} onChange={(value) => setRequestEditor({ ...requestEditor, productCode: value })} /><Field label="الكمية المطلوبة" value={requestEditor.requestedQuantity} inputMode="decimal" onChange={(value) => setRequestEditor({ ...requestEditor, requestedQuantity: value })} required /></div><label className="mt-3 block text-[10px] font-bold text-[#587168]">ملاحظة تشغيلية<textarea value={requestEditor.note} onChange={(event) => setRequestEditor({ ...requestEditor, note: event.target.value })} maxLength={3000} className="mt-1.5 min-h-20 w-full rounded-xl border border-[#d2e1d9] bg-[#fbfdfb] px-3 py-2.5 text-xs text-[#244d44] outline-none focus:border-[#159174]" /></label><div className="mt-3 flex flex-wrap gap-2"><button disabled={updateRequestDetails.isPending} className="inline-flex min-h-10 items-center gap-2 rounded-xl bg-[#123c37] px-3 py-2 text-xs font-bold text-white hover:bg-[#17574b] disabled:opacity-50"><Pencil className="size-4" />{updateRequestDetails.isPending ? "جارٍ حفظ التعديل…" : "حفظ تعديل الطلب"}</button><button type="button" onClick={() => setRequestEditor(undefined)} className="inline-flex min-h-10 items-center gap-2 rounded-xl border border-[#ccdcd4] bg-white px-3 py-2 text-xs font-bold text-[#496b61] hover:bg-[#f1f8f4]">إلغاء التحرير</button></div></form>}</section>}
    {canApproveSupply && <section className="rounded-2xl border border-[#c9e3d5] bg-white p-4 sm:p-5"><div className="flex items-start gap-3"><Building2 className="mt-0.5 size-5 text-[#1e745d]" /><div><h3 className="text-sm font-bold text-[#244d44]">دفتر جهات الموردين</h3><p className="mt-1 text-[10px] leading-5 text-[#71867d]">احفظ أو عدّل أي رقم مورد من هنا. فتح WhatsApp اختياري للمراجعة اليدوية فقط، ولا يُنشئ طلبًا أو يرسل رسالة تلقائيًا.</p></div></div><form onSubmit={(event) => { event.preventDefault(); if (!workspaceId) return; saveSupplierContact.mutate({ workspaceId, supplierId: supplierContactEditor.supplierId, name: supplierContactEditor.name, contactLabel: supplierContactEditor.contactLabel.trim() || undefined, contactPhone: supplierContactEditor.contactPhone.trim() || undefined, isActive: supplierContactEditor.isActive }); }} className="mt-4 grid gap-2 sm:grid-cols-2 lg:grid-cols-4"><input value={supplierContactEditor.name} onChange={(event) => setSupplierContactEditor({ ...supplierContactEditor, name: event.target.value })} placeholder="اسم المورد" required className="min-h-10 rounded-xl border border-[#d2e1d9] bg-[#fbfdfb] px-3 text-xs font-bold text-[#244d44] outline-none focus:border-[#159174]" /><input value={supplierContactEditor.contactLabel} onChange={(event) => setSupplierContactEditor({ ...supplierContactEditor, contactLabel: event.target.value })} placeholder="جهة الاتصال (اختياري)" className="min-h-10 rounded-xl border border-[#d2e1d9] bg-[#fbfdfb] px-3 text-xs font-bold text-[#244d44] outline-none focus:border-[#159174]" /><input value={supplierContactEditor.contactPhone} inputMode="tel" onChange={(event) => setSupplierContactEditor({ ...supplierContactEditor, contactPhone: event.target.value })} placeholder="رقم هاتف / WhatsApp" className="min-h-10 rounded-xl border border-[#d2e1d9] bg-[#fbfdfb] px-3 text-xs font-bold text-[#244d44] outline-none focus:border-[#159174]" /><button disabled={saveSupplierContact.isPending || !supplierContactEditor.name.trim()} className="inline-flex min-h-10 items-center justify-center gap-2 rounded-xl bg-[#123c37] px-3 py-2 text-xs font-bold text-white hover:bg-[#17574b] disabled:opacity-50"><Building2 className="size-4" />{saveSupplierContact.isPending ? "جارٍ الحفظ…" : supplierContactEditor.supplierId ? "حفظ تعديل المورد" : "حفظ المورد"}</button></form><div className="mt-4 grid gap-2 lg:grid-cols-2">{supplierContacts.data?.length ? supplierContacts.data.map((supplier) => <div key={supplier.id} className="rounded-xl border border-[#e0ebe5] bg-[#fbfdfb] p-3"><div className="flex items-start justify-between gap-2"><div><p className="text-xs font-bold text-[#254c42]">{supplier.name}</p><p className="mt-1 text-[10px] text-[#71867d]">{supplier.contactLabel || "لا توجد جهة اتصال مسماة"}{supplier.contactPhone ? ` · ${supplier.contactPhone}` : " · بلا رقم"}</p></div><span className={`rounded-md px-2 py-1 text-[9px] font-bold ${supplier.isActive ? "bg-[#edf8f2] text-[#247055]" : "bg-[#f3f5f4] text-[#718078]"}`}>{supplier.isActive ? "نشط" : "موقوف"}</span></div><div className="mt-3 flex flex-wrap gap-2"><button type="button" onClick={() => setSupplierContactEditor({ supplierId: supplier.id, name: supplier.name, contactLabel: supplier.contactLabel ?? "", contactPhone: supplier.contactPhone ?? "", isActive: supplier.isActive })} className="inline-flex min-h-9 items-center gap-1.5 rounded-lg border border-[#c9ddd3] bg-white px-2.5 py-1.5 text-[10px] font-bold text-[#316459] hover:bg-[#edf8f2]"><Pencil className="size-3.5" />تعديل</button>{supplier.contactPhone && <a href={whatsappLink(supplier.contactPhone, "مرحبًا، بخصوص طلب الصيدلية.")} target="_blank" rel="noreferrer" className="inline-flex min-h-9 items-center gap-1.5 rounded-lg border border-[#c9ddd3] bg-white px-2.5 py-1.5 text-[10px] font-bold text-[#316459] hover:bg-[#edf8f2]"><Phone className="size-3.5" />فتح WhatsApp للمراجعة</a>}</div></div>) : <p className="rounded-xl border border-dashed border-[#d8e7df] px-3 py-5 text-center text-[10px] text-[#72877f] lg:col-span-2">أضف أول مورد ورقم تواصله من النموذج أعلاه.</p>}</div></section>}
    {canApproveSupply && <section className="rounded-2xl border border-[#bcdacc] bg-[linear-gradient(120deg,#eff9f3,#fbfdfb)] p-4 sm:p-5"><div className="flex items-start gap-3"><ShieldCheck className="mt-0.5 size-5 text-[#176f59]" /><div><h3 className="text-sm font-bold text-[#244d44]">مركز تحكم المدير</h3><p className="mt-1 text-[10px] leading-5 text-[#668078]">هذه مساحة تحكم واحدة للمدير: الطلبات وبيانات الاتصال والتوريد والفريق والموردون والقوالب. تبقى قرارات التوريد والرسائل يدوية ومراجَعة، ولا يحصل موظف الطلبات على هذه الأقسام.</p></div></div><div className="mt-4 grid gap-2 sm:grid-cols-2 lg:grid-cols-4"><ControlScope title="بيانات العملاء" detail="تعديل الاسم والرقم والصنف والكمية ضمن الحواجز التشغيلية." /><ControlScope title="فريق الطلبات" detail="أكواد الموظفين، الأداء، ودعوات الدخول المقيدة." /><ControlScope title="الموردون" detail="مواعيد الوصول ودفتر الأرقام دون تغيير تلقائي للمخزون." /><ControlScope title="الرسائل" detail="قوالب التحديث ومراجعة WhatsApp قبل الإرسال البشري." /></div></section>}
    {canApproveSupply && <section className="rounded-2xl border border-[#c9e3d5] bg-white p-4 sm:p-5"><div className="flex items-start justify-between gap-3"><div className="flex items-start gap-3"><DatabaseZap className="mt-0.5 size-5 text-[#1e745d]" /><div><h3 className="text-sm font-bold text-[#244d44]">صحة التشغيل والاسترداد اليدوي</h3><p className="mt-1 text-[10px] leading-5 text-[#71867d]">تفحص هذه البطاقة اتصال سجلات التشغيل وسياسة الاحتفاظ والنشاط الأخير. التصدير ينشئ لقطة محلية بطلبك فقط؛ وهو ليس إرسالًا ولا نسخًا آليًا للملفات المصدرية.</p></div></div><button type="button" onClick={() => workspaceId && exportOperationalSnapshot.mutate({ workspaceId })} disabled={exportOperationalSnapshot.isPending} className="inline-flex min-h-10 items-center gap-2 rounded-xl border border-[#b7d8c9] bg-[#f1faf5] px-3 py-2 text-xs font-bold text-[#1f6b53] hover:bg-[#e4f4eb] disabled:opacity-50"><Download className="size-4" />{exportOperationalSnapshot.isPending ? "جارٍ تجهيز اللقطة…" : "تنزيل لقطة تشغيلية"}</button></div><div className="mt-4 grid gap-2 sm:grid-cols-2 lg:grid-cols-4"><InsightMetric label="قاعدة البيانات" value={reliabilitySnapshot.data?.databaseStatus === "available" ? 1 : null} suffix="متاحة" tone="green" /><InsightMetric label="طلبات مفتوحة" value={reliabilitySnapshot.data?.requestMetrics.openCount} suffix="طلب" tone="amber" /><InsightMetric label="موردون نشطون" value={reliabilitySnapshot.data?.activeSupplierContacts} suffix="مورد" tone="blue" /><InsightMetric label="وصول يحتاج متابعة" value={reliabilitySnapshot.data?.scheduledSupplierArrivals} suffix="موعد" tone="slate" /></div><p className="mt-3 rounded-lg bg-[#f7faf8] px-3 py-2 text-[9px] leading-5 text-[#627b72]">آخر سجل: {reliabilitySnapshot.data?.lastAuditEventAt ? new Date(reliabilitySnapshot.data.lastAuditEventAt).toLocaleString("ar-EG", { dateStyle: "medium", timeStyle: "short" }) : "لا توجد سجلات ظاهرة بعد"} · الاحتفاظ بسجل التدقيق: {reliabilitySnapshot.data?.retentionPolicy.auditEventRetentionDays?.toLocaleString("ar-EG") ?? "—"} يومًا. {reliabilitySnapshot.data?.privacyBoundary ?? ""}</p></section>}
    {canUseRequests && <section className="rounded-2xl border border-[#dbe9e2] bg-white p-4 sm:p-5"><div className="flex items-start gap-3"><ClipboardPlus className="mt-0.5 size-5 text-[#1e745d]" /><div><h3 className="text-sm font-bold text-[#244d44]">قائمة عمل اليوم</h3><p className="mt-1 text-[10px] leading-5 text-[#71867d]">تعتمد على حالة طلبات العملاء وساعات الانتظار الفعلية. الموظف يرى طلباته التي أنشأها فقط؛ المدير يرى قائمة مساحة العمل.</p></div></div><div className="mt-4 grid gap-2 lg:grid-cols-2">{dailyWorkQueue.isLoading && <p className="text-[10px] text-[#72877f]">جارٍ تجهيز أولويات اليوم…</p>}{!dailyWorkQueue.isLoading && !dailyWorkQueue.data?.length && <p className="rounded-xl border border-dashed border-[#d8e7df] px-3 py-5 text-center text-[10px] text-[#72877f] lg:col-span-2">لا توجد طلبات مفتوحة تحتاج متابعة الآن.</p>}{dailyWorkQueue.data?.slice(0, 8).map((task) => <div key={`daily-${task.id}`} className={`rounded-xl border p-3 ${task.isOverdue ? "border-[#ead3a4] bg-[#fffaf0]" : "border-[#e0ebe5] bg-[#fbfdfb]"}`}><div className="flex items-start justify-between gap-2"><div><p className="text-xs font-bold text-[#254c42]">{task.customerName} · {task.productName}</p><p className="mt-1 text-[10px] leading-4 text-[#6d8279]">{task.action}</p></div><span className={`rounded-md border px-2 py-1 text-[9px] font-bold ${statusMeta[task.status as RequestStatus].className}`}>{statusMeta[task.status as RequestStatus].label}</span></div><p className={`mt-2 text-[9px] font-bold ${task.isOverdue ? "text-[#8b651f]" : "text-[#668078]"}`}>{task.isOverdue ? "متأخر أكثر من 24 ساعة" : `عمر الطلب ${Math.max(0, Math.round(task.ageHours)).toLocaleString("ar-EG")} ساعة`}</p></div>)}</div></section>}
  </section>;
}

function DecisionCard({ icon: Icon, title, value, note, tone }: { icon: typeof PackageCheck; title: string; value: number; note: string; tone: "amber" | "green" | "rose" }) {
  const colors = tone === "amber" ? "border-[#ead8a7] bg-[#fffaf0] text-[#88641b]" : tone === "green" ? "border-[#c7e4d4] bg-[#f2fbf6] text-[#227154]" : "border-[#ebd2cd] bg-[#fff4f2] text-[#9b4b40]";
  return <div className={`rounded-2xl border p-4 ${colors}`}><div className="flex items-start justify-between gap-3"><div><p className="text-[10px] font-bold opacity-80">{title}</p><p className="mt-1 text-2xl font-bold">{value.toLocaleString("ar-EG")}</p></div><Icon className="size-5" /></div><p className="mt-2 text-[10px] leading-5 opacity-80">{note}</p></div>;
}

function Metric({ label, value, tone }: { label: string; value: string | number; tone: "amber" | "green" | "plain" }) {
  const classes = tone === "amber" ? "border-[#e4c572]/30 bg-[#d8a345]/15 text-[#fff0c3]" : tone === "green" ? "border-[#94ceb8]/30 bg-[#5cae8b]/15 text-[#e4f7ed]" : "border-white/15 bg-white/8 text-[#e8f2ee]";
  return <div className={`rounded-xl border px-3 py-2.5 ${classes}`}><p className="text-[9px] font-bold opacity-80">{label}</p><p className="mt-1 text-base font-bold">{typeof value === "number" ? value.toLocaleString("ar-EG") : value}</p></div>;
}

function InsightMetric({ label, value, suffix, tone }: { label: string; value?: number | null; suffix: string; tone: "slate" | "amber" | "green" | "blue" }) {
  const colors = { slate: "border-[#d8e8df] bg-white text-[#31574d]", amber: "border-[#ead8a7] bg-[#fffaf0] text-[#8a6618]", green: "border-[#c5e1d1] bg-[#f2fbf6] text-[#23705a]", blue: "border-[#c9e0eb] bg-[#f2fbff] text-[#28667d]" };
  const display = value === null || value === undefined ? "—" : value.toLocaleString("ar-EG", { maximumFractionDigits: 1 });
  return <div className={`rounded-xl border p-3 ${colors[tone]}`}><p className="text-[9px] font-bold opacity-75">{label}</p><p className="mt-1 text-lg font-bold">{display}<span className="mr-1 text-[9px] font-semibold opacity-75">{value === null || value === undefined ? "" : suffix}</span></p></div>;
}

function MiniMetric({ label, value }: { label: string; value: string | number }) {
  return <div className="rounded-lg border border-[#e1ebe5] bg-white px-1.5 py-2"><p className="text-[8px] font-bold text-[#789087]">{label}</p><p className="mt-1 text-[11px] font-bold text-[#285247]">{typeof value === "number" ? value.toLocaleString("ar-EG") : value}</p></div>;
}

function ControlScope({ title, detail }: { title: string; detail: string }) {
  return <div className="rounded-xl border border-[#d5e8dd] bg-white/80 p-3"><p className="text-[10px] font-bold text-[#21624f]">{title}</p><p className="mt-1 text-[9px] leading-4 text-[#6b8279]">{detail}</p></div>;
}

function Field({ label, value, onChange, required, inputMode }: { label: string; value: string; onChange: (value: string) => void; required?: boolean; inputMode?: React.HTMLAttributes<HTMLInputElement>["inputMode"] }) {
  return <label className="block text-[10px] font-bold text-[#59736a]">{label}{required && <span className="mr-1 text-[#a24b40]">*</span>}<input value={value} required={required} inputMode={inputMode} onChange={(event) => onChange(event.target.value)} className="mt-1.5 min-h-10 w-full rounded-xl border border-[#d2e1d9] bg-[#fbfdfb] px-3 py-2 text-xs font-bold text-[#244d44] outline-none focus:border-[#159174]" /></label>;
}
